<script setup lang="ts">
const props=defineProps<{periodStart:string;periodEnd:string}>();const{loadInventoryOverview}=useAppData();const{notify}=useUi();const loading=ref(true),movements=ref<any[]>([]),total=ref(0),page=ref(0),search=ref(''),resource=ref('Todos'),type=ref('Todos');const pageSize=100;const resourceLabel=(value:string)=>value==='filaments'?'Filamento':'Produto fabricado';const resourceUnit=(value:string)=>value==='filaments'?'g':'un.';const movementLabel=(value:string)=>value==='in'?'Entrada':value==='out'?'Saída':'Ajuste';const movementSign=(value:string)=>value==='in'?'+':value==='out'?'-':'=';const load=async(reset=false)=>{if(reset)page.value=0;loading.value=true;try{const result=await loadInventoryOverview({from:props.periodStart,to:props.periodEnd,resource:resource.value==='Todos'?'':resource.value,type:type.value==='Todos'?'':type.value,search:search.value,limit:pageSize,offset:page.value*pageSize});movements.value=result.movements;total.value=result.total}catch(error:any){notify(error?.data?.error||error?.message||'Não foi possível carregar as movimentações.','info')}finally{loading.value=false}};watch(()=>[props.periodStart,props.periodEnd],()=>load(true),{immediate:true})</script>
<template><div><div class="report-intro"><div><h2>Movimentações de estoque</h2><p>Entradas, saídas e ajustes reais registrados no período selecionado.</p></div><button class="btn" type="button" :disabled="loading" @click="load(true)"><UiIcon name="refresh" :size="16"/>Atualizar</button></div><div class="filters inventory-filters"><div class="field field--search"><label>Buscar</label><div class="search-field"><UiIcon name="search" :size="16"/><input v-model="search" placeholder="Item ou motivo" @keyup.enter="load(true)"></div></div><div class="field"><label>Estoque</label><select v-model="resource" @change="load(true)"><option>Todos</option><option value="filaments">Filamentos</option><option value="products">Produtos fabricados</option></select></div><div class="field"><label>Operação</label><select v-model="type" @change="load(true)"><option>Todos</option><option value="in">Entradas</option><option value="out">Saídas</option><option value="adjustment">Ajustes</option></select></div></div><PanelCard><div v-if="loading" class="empty-state">Carregando movimentações...</div><div v-else-if="!movements.length" class="empty-state"><div><div class="empty-state__icon"><UiIcon name="history"/></div><h3>Nenhuma movimentação encontrada</h3><p>Altere os filtros ou registre uma movimentação no Estoque.</p></div></div><div v-else class="table-scroll"><table class="data-table"><thead><tr><th>Data</th><th>Item</th><th>Estoque</th><th>Operação</th><th>Quantidade</th><th>Saldo após</th><th>Motivo</th></tr></thead><tbody><tr v-for="item in movements" :key="item.id"><td>{{new Date(item.createdAt).toLocaleString('pt-BR')}}</td><td><strong>{{item.resourceName||'Item removido'}}</strong></td><td>{{resourceLabel(item.resource)}}</td><td><span class="badge" :class="item.type==='in'?'badge--green':item.type==='out'?'badge--red':'badge--orange'">{{movementLabel(item.type)}}</span></td><td :class="item.type==='out'?'money-negative':item.type==='in'?'money-positive':''"><strong>{{movementSign(item.type)}}{{formatNumber(item.quantity)}} {{resourceUnit(item.resource)}}</strong></td><td>{{formatNumber(item.resultingQuantity)}} {{resourceUnit(item.resource)}}</td><td>{{item.reason}}</td></tr></tbody></table></div><div v-if="total>pageSize" class="report-pager"><span>Mostrando {{page*pageSize+1}}–{{Math.min((page+1)*pageSize,total)}} de {{total}}</span><button class="btn btn--small" :disabled="!page||loading" @click="page--;load()">Anterior</button><button class="btn btn--small" :disabled="(page+1)*pageSize>=total||loading" @click="page++;load()">Próxima</button></div></PanelCard></div></template>
<style scoped>.report-intro{display:flex;align-items:end;justify-content:space-between;gap:16px;margin-bottom:14px}.report-intro h2{margin:0;font-size:20px}.report-intro p{margin:5px 0 0;color:var(--muted);font-size:12px}.inventory-filters{grid-template-columns:minmax(220px,1fr) repeat(2,minmax(130px,.35fr))}.report-pager{display:flex;justify-content:flex-end;align-items:center;gap:8px;padding:14px 16px;color:#687386;font-size:12px}@media(max-width:620px){.report-intro{align-items:stretch;flex-direction:column}.inventory-filters{grid-template-columns:1fr}.report-pager{justify-content:flex-start;flex-wrap:wrap}}</style>
